select
  'statistics-for-social-work',
  null,
  'Statistics for Social Work',
  'Statistics for Social Work',
  'Develop statistical literacy for ethical, evidence-informed social-work practice. Students learn to describe service populations, evaluate research and programs, quantify uncertainty, select and check analyses, use statistical software reproducibly, and communicate findings without overstating what the data can support.',
  $stswjson${"slug": "statistics-for-social-work", "title": "Statistics for Social Work", "description": "Develop statistical literacy for ethical, evidence-informed social-work practice. Students learn to describe service populations, evaluate research and programs, quantify uncertainty, select and check analyses, use statistical software reproducibly, and communicate findings without overstating what the data can support.", "topics": [{"id": "3fc412ee-05b2-4507-8e38-bdae5bb503bd", "type": "topic", "title": "Descriptive statistics", "description": "Descriptive statistics turn case, agency, and community data into an honest picture of who was observed and what patterns are present. They are the foundation for every later analysis.", "children": [{"id": "773018ca-74fb-4bed-8475-d166e5275959", "type": "subtopic", "title": "Variables and measurement", "children": [{"id": "4676804e-f168-4ec3-afc4-fd66d1aab415", "type": "concept", "title": "Units of analysis: person, family, group, program, organization, neighborhood, and time"}, {"id": "8b31991d-48b6-466b-b340-2579bc33bac6", "type": "concept", "title": "Categorical, ordinal, interval, ratio, count, rate, and time-to-event variables"}, {"id": "44b074e0-890b-46eb-b96e-c929c8f7574b", "type": "concept", "title": "Operational definitions, coding schemes, reliability, validity, and measurement error"}, {"id": "42d85c0d-90ce-46b7-abfd-1600b4134c27", "type": "concept", "title": "Race, ethnicity, gender, disability, identity, and other equity variables: disaggregation without reification"}], "description": "Why it matters. Connect a social-work concept to a defensible data representation."}, {"id": "3b016eaa-20cf-4428-89e4-f64020b2c4da", "type": "subtopic", "title": "Summaries of center and spread", "children": [{"id": "e54df1db-c80c-4e94-ae5d-3aa89be7a62d", "type": "concept", "title": "Frequency tables, proportions, percentages, rates, and prevalence"}, {"id": "508b59e2-edd3-4644-a499-10d3f8df7ca3", "type": "concept", "title": "Mean, median, mode, quantiles, and trimmed summaries"}, {"id": "92c0105b-7e87-4ec2-b8e7-227ff11781a5", "type": "concept", "title": "Range, interquartile range, variance, standard deviation, and median absolute deviation"}, {"id": "f102a1ed-0d9a-489f-9aee-b821d2409dfc", "type": "concept", "title": "Skewness, outliers, floor and ceiling effects, and robust summaries"}], "description": "Why it matters. Choose summaries that match the scale, shape, and purpose of the data."}, {"id": "5ad5f445-2baa-49fd-8279-903d92ffe614", "type": "subtopic", "title": "Visualization and data quality", "children": [{"id": "42079670-aa11-45ef-a3ff-08dae735aadc", "type": "concept", "title": "Bar charts, histograms, boxplots, dot plots, density displays, and time-series plots"}, {"id": "ac02714f-fcbc-4494-b9f6-c14d06cf6b38", "type": "concept", "title": "Clear titles, denominators, axes, units, uncertainty, accessibility, and source notes"}, {"id": "0e53ad21-030a-41a0-ae39-a57f93b28ce2", "type": "concept", "title": "Missingness, impossible values, duplicates, recoding, and data dictionaries"}, {"id": "633cc58c-6f1d-4a17-a8d0-5b6403e0d18b", "type": "concept", "title": "Misleading scales, truncated axes, overplotting, small cells, confidentiality, and stigmatizing displays"}], "description": "Why it matters. Make patterns and limitations visible before formal testing."}]}, {"id": "4d6f5d13-ec4b-435f-a3f1-db5c34db9206", "type": "topic", "title": "Probability", "description": "Probability provides a language for uncertainty, risk, and variation. Social workers use it to understand screening, prediction, sampling, and the limits of evidence.", "children": [{"id": "723c4ac6-8e66-4615-971e-8cffba1c6853", "type": "subtopic", "title": "Probability foundations", "children": [{"id": "c4768f37-07c4-4ce6-8377-49de9b3a3151", "type": "concept", "title": "Outcomes, events, complements, unions, intersections, and mutually exclusive events"}, {"id": "4e8a4904-c3f5-434a-9a3d-1dfa5de6073b", "type": "concept", "title": "Addition and multiplication rules; independence versus association"}, {"id": "73667d28-d077-49ea-ba56-757abf275f02", "type": "concept", "title": "Conditional probability, joint and marginal probability, and contingency tables"}, {"id": "fd2d2155-8622-47ef-9ef4-23e069e8b98f", "type": "concept", "title": "Base rates, natural frequencies, and common probability misconceptions"}], "description": "Why it matters. Reason carefully about events and conditional information."}, {"id": "39ff8412-ce01-49d6-ad34-ef92b59ef33a", "type": "subtopic", "title": "Distributions and random variables", "children": [{"id": "4880b5ca-568f-4396-a92a-628250132d7d", "type": "concept", "title": "Discrete and continuous random variables; expected value and variance"}, {"id": "fc4824c2-34bb-4bd5-b253-4da6bf0ced7b", "type": "concept", "title": "Bernoulli, binomial, normal, and sampling distributions"}, {"id": "88014237-3b6c-4ceb-9401-5f7683ab6860", "type": "concept", "title": "Standard scores, percentiles, the normal model, and when normality is implausible"}, {"id": "eb1cd27a-deb0-40a1-b437-bb5b34804ee3", "type": "concept", "title": "Central Limit Theorem as a bridge from samples to inference"}], "description": "Why it matters. Use probability models as simplified representations rather than literal truth."}, {"id": "0ae2bc6e-18ab-41b5-af88-cddb6eca611e", "type": "subtopic", "title": "Risk, screening, and decisions", "children": [{"id": "1c0c8943-154f-4594-9785-cc0f8e5370a7", "type": "concept", "title": "Sensitivity, specificity, predictive values, false positives, and false negatives"}, {"id": "03ee822f-2df5-449b-9a40-cf3faf0c08af", "type": "concept", "title": "Prevalence and the base-rate effect on predictive value"}, {"id": "94cc82e1-785d-48a8-b727-e23761e53a47", "type": "concept", "title": "Absolute risk, relative risk, odds, risk difference, and number needed to treat/help"}, {"id": "8a74e6be-78e7-4be3-8795-7734b83e048a", "type": "concept", "title": "Threshold choices, unequal error costs, calibration, fairness, and limits of actuarial tools"}], "description": "Why it matters. Translate probabilities into clinically and ethically meaningful judgments."}]}, {"id": "bda4bed6-a607-4e9e-824e-eef17f9a55e2", "type": "topic", "title": "Sampling", "description": "Sampling determines what population a study can credibly describe. Students learn to separate statistical precision from representativeness and ethical recruitment.", "children": [{"id": "c7d3e38f-e07b-4f15-8de4-0216239d08f7", "type": "subtopic", "title": "Populations and sampling frames", "children": [{"id": "eede98d7-1495-4bd9-a4bb-7673357bf8c6", "type": "concept", "title": "Target, accessible, study, and analytic populations"}, {"id": "c2f5a324-2cee-4226-a318-09cb5519a145", "type": "concept", "title": "Sampling frames, coverage error, eligibility, recruitment, consent, and attrition"}, {"id": "cbc7e188-b75e-4a82-9098-e8700a0b4174", "type": "concept", "title": "Probability versus nonprobability samples"}, {"id": "4059071e-47ce-4c68-b104-a872ef020dc2", "type": "concept", "title": "Agency records, service users, hidden populations, online samples, and community-based recruitment"}], "description": "Why it matters. Define who the evidence is meant to represent and who could actually be reached."}, {"id": "a48d9c9d-47de-4243-a8f7-d0e61d6c05df", "type": "subtopic", "title": "Sampling designs", "children": [{"id": "eaaf8842-4758-4811-9433-09217a4e4193", "type": "concept", "title": "Simple random, systematic, stratified, cluster, and multistage sampling"}, {"id": "bd44340f-b4f6-4b06-b467-d8dc0fc15e76", "type": "concept", "title": "Convenience, purposive, quota, snowball, respondent-driven, and time-location sampling"}, {"id": "1aec6a99-92f1-4ff2-8672-104c82a29fd6", "type": "concept", "title": "Oversampling small or marginalized groups and the need for weights"}, {"id": "d60f8879-f8ae-4cee-a81e-66a82a782467", "type": "concept", "title": "Design effects, intraclass correlation, finite populations, and multilevel structure"}], "description": "Why it matters. Match a design to logistics, equity, and analytic goals."}, {"id": "55ca1311-d121-4650-9b12-fbaa44f61daf", "type": "subtopic", "title": "Bias, precision, and power", "children": [{"id": "5f18b5b3-dfbd-4e47-97fd-8a88556f5e9c", "type": "concept", "title": "Sampling variability, standard errors, margins of error, and confidence levels"}, {"id": "68c1da81-cc6c-4234-92b7-902403c7978f", "type": "concept", "title": "Selection, nonresponse, survivorship, volunteer, and attrition bias"}, {"id": "6aa12a5f-6b03-4f32-82e3-0725dcc1be11", "type": "concept", "title": "Power, minimum detectable effect, practical significance, and feasibility"}, {"id": "937a05de-99b2-4001-ad3b-cbaa83354da0", "type": "concept", "title": "Weighting, poststratification, missing-data adjustments, and transparent limits to generalization"}], "description": "Why it matters. Distinguish the size of a sample from the quality of its information."}]}, {"id": "383787dd-9422-46db-9de4-819c61c5e47c", "type": "topic", "title": "Hypothesis testing and estimation", "description": "Statistical inference quantifies how compatible the observed data are with models and hypotheses. The goal is calibrated evidence, not a mechanical hunt for p-values.", "children": [{"id": "684795cb-c80d-4429-9c27-981d04605d32", "type": "subtopic", "title": "Questions, estimands, and hypotheses", "children": [{"id": "cd508144-28a0-4b23-97fe-7e3331820d95", "type": "concept", "title": "Research question, population, comparison, outcome, time, and estimand"}, {"id": "9230c588-30c1-4420-92e9-89e54ffffaea", "type": "concept", "title": "Null and alternative hypotheses; directional and nondirectional tests"}, {"id": "aa6b2c62-8308-4e73-9599-1d603438d58e", "type": "concept", "title": "Point estimates, standard errors, sampling distributions, and confidence intervals"}, {"id": "bf944c2e-c14b-4916-b22b-996ababa9c03", "type": "concept", "title": "Descriptive, associational, predictive, and causal questions"}], "description": "Why it matters. Start with the decision-relevant quantity before choosing a test."}, {"id": "358249bb-8f39-4260-9f37-00b2bf9efc86", "type": "subtopic", "title": "Testing logic and errors", "children": [{"id": "f0bdaa5c-4a87-41f8-89ca-afafc3d9a319", "type": "concept", "title": "Test statistics, p-values, alpha, and rejection regions"}, {"id": "cfd71c49-5063-4ce1-959b-bc0510ddb123", "type": "concept", "title": "Type I and Type II errors, power, and consequences of errors"}, {"id": "c1b273fb-ee4b-464c-b8d7-9fe7fcfcc799", "type": "concept", "title": "Statistical significance versus effect size, precision, practical importance, and equity"}, {"id": "3136168b-d1b9-434a-a824-5c9a319cdbac", "type": "concept", "title": "Multiple testing, selective reporting, p-hacking, preregistration, and replication"}], "description": "Why it matters. Interpret uncertainty without treating a threshold as proof."}, {"id": "b2a0dda2-354e-4682-b794-ef60b841dd4a", "type": "subtopic", "title": "Assumptions and transparent reporting", "children": [{"id": "7803a7da-0262-4102-a8f6-f29621a67ea5", "type": "concept", "title": "Independence, distributional shape, equal variance, scale, and sample-size conditions"}, {"id": "eea13aee-64ac-4763-9d24-b0fd7ac4fe80", "type": "concept", "title": "Outliers, influential cases, missingness, and sensitivity analysis"}, {"id": "b40a574e-1446-4404-9c60-f93340481b39", "type": "concept", "title": "Exact tests, permutation approaches, bootstrap intervals, and nonparametric alternatives"}, {"id": "6359f50c-566c-4379-8f2e-2d0d630c5568", "type": "concept", "title": "Estimate, interval, test statistic, degrees of freedom, p-value, effect size, assumptions, and limitations"}], "description": "Why it matters. Check whether the analysis is appropriate and report enough for others to evaluate it."}]}, {"id": "b1f71877-dc5b-4328-b030-4c54a78462ae", "type": "topic", "title": "Chi-square and categorical data", "description": "Chi-square methods test patterns among categorical variables common in social-work data, while effect sizes and cell counts reveal what a p-value alone cannot.", "children": [{"id": "24bee209-2c1a-46dc-a625-265368600025", "type": "subtopic", "title": "Tables and questions", "children": [{"id": "23146828-525e-42bf-9db2-933391bd1489", "type": "concept", "title": "Counts versus row, column, and total percentages"}, {"id": "d5672afc-11f7-4ae3-9534-00a6e2836061", "type": "concept", "title": "Tests of independence, homogeneity, and goodness of fit"}, {"id": "066c7ac0-d6d4-4abd-b5dc-ddcffe4f1472", "type": "concept", "title": "Observed and expected counts; residuals and contribution to chi-square"}, {"id": "133c2bfc-ecc1-48da-bd16-92276816a6ec", "type": "concept", "title": "Risk difference, risk ratio, odds ratio, and prevalence ratio"}], "description": "Why it matters. Build interpretable cross-tabulations with appropriate denominators."}, {"id": "7a279c00-58a9-4da1-8de2-a916371b0b83", "type": "subtopic", "title": "Conditions and alternatives", "children": [{"id": "bd0b2f50-1bf1-492b-bd5c-a374cb3ce5e6", "type": "concept", "title": "Independent observations, mutually exclusive categories, and adequate expected counts"}, {"id": "05ffd734-5ecc-4785-bc06-6e1cef99fcb2", "type": "concept", "title": "Sparse cells, structural zeros, small groups, and disclosure risk"}, {"id": "e4076c31-8ac6-48a8-bd6c-6df87a85ccc3", "type": "concept", "title": "Fisher exact test, exact or Monte Carlo methods, and category decisions"}, {"id": "cbb90616-52c4-44e5-a2ff-538a7609ddeb", "type": "concept", "title": "Paired binary data and McNemar test as a distinct design"}], "description": "Why it matters. Recognize when asymptotic chi-square results are unreliable."}, {"id": "c109616a-c001-4fcb-b675-eddf9f3532ca", "type": "subtopic", "title": "Interpretation for practice", "children": [{"id": "fe46ef8d-0b94-45f7-a2d4-737b13922613", "type": "concept", "title": "Cramer V, phi, odds ratios, and confidence intervals"}, {"id": "946331f5-0a7b-4ab0-aecb-320d4f43bd40", "type": "concept", "title": "Stratified tables, confounding, Simpson paradox, and effect modification"}, {"id": "dc29de72-5689-4a8e-a014-db4a160cf2db", "type": "concept", "title": "Adjusted residuals and careful follow-up comparisons"}, {"id": "35ba33a3-abe0-486a-ba53-6cd9ae763a76", "type": "concept", "title": "Avoiding causal language, deficit framing, and overinterpretation of small subgroup cells"}], "description": "Why it matters. Describe the pattern, size, uncertainty, and limitations."}]}, {"id": "cbda4a14-2e3e-4712-bc68-ea1e332c3f96", "type": "topic", "title": "t-tests and mean comparisons", "description": "t-tests compare means while accounting for sampling variability. Students learn that design, assumptions, effect size, and interval estimates matter more than memorizing formulas.", "children": [{"id": "f65f7bd5-ee72-4546-a629-2a2d255828f3", "type": "subtopic", "title": "Choosing the comparison", "children": [{"id": "248ebe0b-8be4-44a0-80f7-cd87292a8ce5", "type": "concept", "title": "One-sample t-test for a benchmark"}, {"id": "df82480e-112f-463d-8fe1-87d231872eab", "type": "concept", "title": "Independent-samples t-test for separate groups"}, {"id": "031030b9-44bf-4448-af5e-a54f808e6d79", "type": "concept", "title": "Paired-samples t-test for matched or repeated observations"}, {"id": "cb9fd5d6-07d6-4bad-880e-d9bf1de43eb6", "type": "concept", "title": "Difference scores, pairing, independence, and clustering"}], "description": "Why it matters. Select the test from the study design, not from the desired result."}, {"id": "7d4c9786-98a6-4947-8a22-5ec416256208", "type": "subtopic", "title": "Assumptions and robust choices", "children": [{"id": "86fd958b-c885-4d1e-904b-5f822ca76588", "type": "concept", "title": "Approximate normality of outcomes or differences; sample-size robustness"}, {"id": "af3e9ce7-7c46-46aa-aff5-50b6412e67f9", "type": "concept", "title": "Welch t-test versus pooled-variance t-test"}, {"id": "e813add5-f3c9-441d-9515-5f8d182afc6e", "type": "concept", "title": "Outliers, skew, bounded scales, and unequal group sizes"}, {"id": "d910c23a-7b75-4ed9-9092-b88b73c7afa4", "type": "concept", "title": "Mann-Whitney, Wilcoxon signed-rank, permutation tests, bootstrap intervals, and their estimands"}], "description": "Why it matters. Evaluate whether mean-based comparison is sensible."}, {"id": "5cf436f7-897a-4a4d-bb3f-db599d58d047", "type": "subtopic", "title": "Effect and reporting", "children": [{"id": "eaedac98-5268-4fcb-9e85-18ad9d60a271", "type": "concept", "title": "Mean difference, standardized mean difference, and confidence interval"}, {"id": "a0039708-a55c-45a3-8640-018b2d86a244", "type": "concept", "title": "Cohen d, Hedges g, paired effect sizes, and practical benchmarks"}, {"id": "42267abd-9917-46c1-87c4-c52ff425c6ac", "type": "concept", "title": "Graphing raw data with summaries rather than bar charts alone"}, {"id": "864a0502-686d-413e-aa44-855484bcd4c3", "type": "concept", "title": "APA-style results plus plain-language and practice implications"}], "description": "Why it matters. Communicate magnitude and uncertainty in terms relevant to clients and programs."}]}, {"id": "acf22144-1384-4938-9739-8469f80cb5ff", "type": "topic", "title": "Analysis of variance", "description": "ANOVA extends mean comparison to multiple groups or conditions. It separates an omnibus question from planned contrasts and guards against uncontrolled testing.", "children": [{"id": "fb0ac33d-fddc-4f43-a3fc-a3e274c9f136", "type": "subtopic", "title": "ANOVA logic and designs", "children": [{"id": "21dca89f-cc92-4613-bdfe-5bf01aa56432", "type": "concept", "title": "Between-group and within-group variation; F statistic"}, {"id": "1d3ec3a2-8df1-43e0-ad8c-ad23e545fb6d", "type": "concept", "title": "One-way between-subjects ANOVA"}, {"id": "afe10da1-6b50-4ce0-9bf2-db3efd431505", "type": "concept", "title": "Repeated-measures and factorial designs as extensions"}, {"id": "d0da57d1-fe57-4d8c-a205-0c2c00065bca", "type": "concept", "title": "Main effects, interactions, nesting, and the limits of simple one-way models"}], "description": "Why it matters. Understand what variance decomposition asks and what it does not establish."}, {"id": "25362c42-b5b6-4c36-b001-a6d5c6e4029d", "type": "subtopic", "title": "Assumptions and follow-up", "children": [{"id": "29e67f34-71b9-44a1-b82e-b2a21f366ce4", "type": "concept", "title": "Independence, residual normality, homogeneity, and influential observations"}, {"id": "efee49b5-0bb3-4f63-ba7a-3b8d05d015f0", "type": "concept", "title": "Welch ANOVA, Kruskal-Wallis, Friedman, permutation, and robust alternatives"}, {"id": "c000c7a1-3fb8-4166-9ed1-754aeea025b1", "type": "concept", "title": "Planned contrasts versus post hoc comparisons"}, {"id": "a9611e35-9dbc-4cc3-bd41-4f2f2dd0e9a7", "type": "concept", "title": "Tukey, Holm, false discovery rate, and familywise error control"}], "description": "Why it matters. Plan comparisons before examining the results when possible."}, {"id": "2c41fbd0-3aa6-43a6-8967-caba444f294a", "type": "subtopic", "title": "Magnitude and interpretation", "children": [{"id": "3113a6d2-ab13-41c2-94f9-971e0f670782", "type": "concept", "title": "Eta squared, omega squared, partial eta squared, and confidence intervals"}, {"id": "1cb3c761-791e-46ee-98cc-4695342ca231", "type": "concept", "title": "Estimated means, contrasts, raw-data plots, and uncertainty intervals"}, {"id": "4cf8c30a-8864-4747-acaf-016e6d093111", "type": "concept", "title": "Interaction plots and heterogeneous program effects"}, {"id": "8fe5884a-a807-46e7-bb62-a7a9597ee284", "type": "concept", "title": "Substantive importance, unequal opportunity, subgroup power, and cautious interpretation"}], "description": "Why it matters. Move beyond a significant omnibus result to meaningful group patterns."}]}, {"id": "c06e28b7-695b-4bdc-b4d1-990e2a635cce", "type": "topic", "title": "Correlation", "description": "Correlation describes how two variables vary together. Students learn to visualize relationships, choose a suitable coefficient, and resist causal interpretations.", "children": [{"id": "c945ba9f-ae96-4c07-8d07-fe30368e76ff", "type": "subtopic", "title": "Association concepts", "children": [{"id": "e7ed2d12-4921-40f0-9dd2-049deb25c53c", "type": "concept", "title": "Scatterplots, covariance, direction, magnitude, and linearity"}, {"id": "eadd76ff-04f5-4650-9ad5-0c17cb512088", "type": "concept", "title": "Pearson correlation and its assumptions"}, {"id": "b834ac4a-b799-4b26-b489-63c7da1fade6", "type": "concept", "title": "Spearman rank and Kendall association for ordinal or monotonic relationships"}, {"id": "9bbc9c87-54da-448b-974b-0633808ddd9d", "type": "concept", "title": "Point-biserial correlation and categorical-variable cautions"}], "description": "Why it matters. Separate direction, strength, form, and prediction."}, {"id": "1afc8053-5fe3-44a7-b924-51e4f1e052d5", "type": "subtopic", "title": "Threats and diagnostics", "children": [{"id": "b4efaad4-8785-4d67-87d3-c75a6f296dfe", "type": "concept", "title": "Outliers, restricted range, nonlinearity, heteroscedasticity, and measurement error"}, {"id": "a40fbad9-d623-4895-9c07-34b653e46ff6", "type": "concept", "title": "Subgroups, ecological fallacy, aggregation, and Simpson paradox"}, {"id": "4f11cee9-b4bc-4d8f-8c1f-93a6c89a960d", "type": "concept", "title": "Common causes, reverse direction, selection, and collider bias"}, {"id": "ed9a5d73-8262-4ffe-a66b-44df41c76dfe", "type": "concept", "title": "Multiple correlations, researcher degrees of freedom, and correction strategies"}], "description": "Why it matters. Identify patterns that can make a coefficient misleading."}, {"id": "d8205f29-b8e7-4d1c-bf51-db4b622abb2d", "type": "subtopic", "title": "Interpretation and communication", "children": [{"id": "8556fdf6-8a57-44df-8670-8a0c725947cf", "type": "concept", "title": "Correlation coefficient, confidence interval, sample size, and plot"}, {"id": "a59d1e57-c5cb-40b0-ac1b-876a74be6104", "type": "concept", "title": "Shared variance and why r-squared is not the percent “caused”"}, {"id": "77a39fc4-d414-47d0-83f1-50d573ea6fd3", "type": "concept", "title": "Practical magnitude depends on outcome, setting, reliability, and decision stakes"}, {"id": "0171dce2-7c39-4f94-ac78-f3cb30e57969", "type": "concept", "title": "Association language, uncertainty, and implications for further study or screening"}], "description": "Why it matters. Report the relationship with uncertainty and context."}]}, {"id": "d3a89a6e-9bd6-4c32-b93f-bd2ddba6269f", "type": "topic", "title": "Regression", "description": "Regression estimates adjusted relationships and supports prediction, but valid interpretation depends on design, specification, diagnostics, and a clear estimand.", "children": [{"id": "da9bff74-d36d-4500-b14a-7696eb56344e", "type": "subtopic", "title": "Simple and multiple regression", "children": [{"id": "9f4d76f6-917f-44d8-9f44-dd57f8daed84", "type": "concept", "title": "Intercept, slope, fitted value, residual, and R-squared"}, {"id": "215c4b6a-04a4-446e-86b2-74216379a609", "type": "concept", "title": "Continuous, binary, categorical, and transformed predictors"}, {"id": "a1974140-9a47-4278-94d2-306e27a71294", "type": "concept", "title": "Dummy coding, reference categories, centering, and standardized coefficients"}, {"id": "664af684-37ed-4acf-8cff-f90f5eec79e8", "type": "concept", "title": "Confounding adjustment, mediation and interaction as distinct questions"}], "description": "Why it matters. Translate a social-work question into an outcome, predictors, and interpretable coefficients."}, {"id": "b1b24da9-a53a-490a-a95d-c2509f178b05", "type": "subtopic", "title": "Model diagnostics and uncertainty", "children": [{"id": "f728c995-2d4a-427b-a494-b8a6ba5104b9", "type": "concept", "title": "Linearity, independence, homoscedasticity, residual distribution, and specification"}, {"id": "aee9696c-f6c8-4fa8-a53e-ebeb0d973329", "type": "concept", "title": "Multicollinearity, variance inflation, influential cases, leverage, and Cook distance"}, {"id": "9d0c0c3e-bd16-4f6d-a3b1-92db9c224b8b", "type": "concept", "title": "Missing data, complete-case analysis, imputation concepts, and sensitivity analysis"}, {"id": "c952b7a1-0290-4282-89be-b07de2b01396", "type": "concept", "title": "Overfitting, train-test separation, cross-validation, and prediction error"}], "description": "Why it matters. Check whether the fitted model adequately represents the data."}, {"id": "5506a626-4d0e-4b97-9e75-653a9ca3254d", "type": "subtopic", "title": "Interpretation, extensions, and ethics", "children": [{"id": "ac97744c-1b92-447b-9aa2-e0c29b33219d", "type": "concept", "title": "Coefficient and confidence-interval interpretation; adjusted predictions and marginal effects"}, {"id": "0ce42e68-cc21-44f3-b203-a9932119187a", "type": "concept", "title": "Logistic regression for binary outcomes and count models as next steps"}, {"id": "02841a5e-f0d6-4872-8b6a-dd92c2e0d8c9", "type": "concept", "title": "Prediction versus explanation versus causal effect; design assumptions for causal claims"}, {"id": "0a7f6843-fe03-43a6-b01b-9a599e42df5a", "type": "concept", "title": "Algorithmic bias, proxy variables, fairness, transparency, and human review in high-stakes decisions"}], "description": "Why it matters. Use regression estimates for the right purpose and communicate limitations."}]}, {"id": "a268d56a-dbe6-4ab5-8f32-83a5e75a5974", "type": "topic", "title": "Statistical software and reproducible practice", "description": "Software should make analysis auditable, not turn judgment into button pressing. Students create a complete workflow from raw data to a defensible result and accessible communication.", "children": [{"id": "01441f75-185f-4e32-98ea-2b38f6f4de98", "type": "subtopic", "title": "Data management workflow", "children": [{"id": "23182a1d-03a4-4679-bca2-fdf1970adc1c", "type": "concept", "title": "Import, variable labels, types, value labels, missing-value codes, and date handling"}, {"id": "f9974970-29ee-4e0d-a538-f83c1b10133e", "type": "concept", "title": "Tidy structure, recoding, derived variables, validation checks, and data dictionaries"}, {"id": "d9086332-6796-44f0-b6f2-582bea5ecb22", "type": "concept", "title": "De-identification, small-cell suppression, secure storage, access control, and retention"}, {"id": "22f3cc35-8792-4f40-8006-a79c58e881c9", "type": "concept", "title": "Raw/read-only, cleaned, analytic, output, and documentation folders"}], "description": "Why it matters. Protect source data while documenting every transformation."}, {"id": "4e7291ef-9a3f-42ea-9bee-69abfd653663", "type": "subtopic", "title": "Reproducible analysis", "children": [{"id": "fb1b156c-a029-47cb-9a1b-175f672c5c56", "type": "concept", "title": "Syntax/scripts rather than undocumented point-and-click steps"}, {"id": "a5e0f520-2238-4ba1-854d-9e080783843d", "type": "concept", "title": "Comments, file paths, seeds, session/software versions, and analysis logs"}, {"id": "a5c4c517-3085-41b6-8660-4f87d4899280", "type": "concept", "title": "Automated tables and figures; export without manual transcription"}, {"id": "dcf4c922-467b-415b-9ccd-be96050937e2", "type": "concept", "title": "Version control concepts, quality checks, reproducibility package, and audit trail"}], "description": "Why it matters. Make results traceable and rerunnable in SPSS syntax, R, jamovi, JASP, or approved software."}, {"id": "e31b6501-30e1-43b5-bf2e-5d80f4f18239", "type": "subtopic", "title": "Practice-facing interpretation", "children": [{"id": "ac34fb4d-4c36-48a0-a3ac-132d74ea2cf2", "type": "concept", "title": "Test selection map based on question, design, variable type, and assumptions"}, {"id": "24a71024-81db-441a-a5f6-091f3017c3f0", "type": "concept", "title": "Tables and graphs that include denominators, estimates, uncertainty, and accessible design"}, {"id": "26dd1274-a93b-498a-bc5b-5b59ec49072d", "type": "concept", "title": "Plain-language results for clients, practitioners, administrators, and community partners"}, {"id": "8d7bd74e-5db0-48df-a48b-5ea16f8e80e8", "type": "concept", "title": "Data-story limits, equity impacts, recommendations, and questions that remain unanswered"}], "description": "Why it matters. Translate numerical output into responsible decisions and evidence-based practice."}]}], "dbBacked": true}$stswjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'statistics-for-social-work'
);

update public.learning_paths
set
  title = 'Statistics for Social Work',
  goal = 'Statistics for Social Work',
  summary = 'Develop statistical literacy for ethical, evidence-informed social-work practice. Students learn to describe service populations, evaluate research and programs, quantify uncertainty, select and check analyses, use statistical software reproducibly, and communicate findings without overstating what the data can support.',
  data = $stswjson${"slug": "statistics-for-social-work", "title": "Statistics for Social Work", "description": "Develop statistical literacy for ethical, evidence-informed social-work practice. Students learn to describe service populations, evaluate research and programs, quantify uncertainty, select and check analyses, use statistical software reproducibly, and communicate findings without overstating what the data can support.", "topics": [{"id": "3fc412ee-05b2-4507-8e38-bdae5bb503bd", "type": "topic", "title": "Descriptive statistics", "description": "Descriptive statistics turn case, agency, and community data into an honest picture of who was observed and what patterns are present. They are the foundation for every later analysis.", "children": [{"id": "773018ca-74fb-4bed-8475-d166e5275959", "type": "subtopic", "title": "Variables and measurement", "children": [{"id": "4676804e-f168-4ec3-afc4-fd66d1aab415", "type": "concept", "title": "Units of analysis: person, family, group, program, organization, neighborhood, and time"}, {"id": "8b31991d-48b6-466b-b340-2579bc33bac6", "type": "concept", "title": "Categorical, ordinal, interval, ratio, count, rate, and time-to-event variables"}, {"id": "44b074e0-890b-46eb-b96e-c929c8f7574b", "type": "concept", "title": "Operational definitions, coding schemes, reliability, validity, and measurement error"}, {"id": "42d85c0d-90ce-46b7-abfd-1600b4134c27", "type": "concept", "title": "Race, ethnicity, gender, disability, identity, and other equity variables: disaggregation without reification"}], "description": "Why it matters. Connect a social-work concept to a defensible data representation."}, {"id": "3b016eaa-20cf-4428-89e4-f64020b2c4da", "type": "subtopic", "title": "Summaries of center and spread", "children": [{"id": "e54df1db-c80c-4e94-ae5d-3aa89be7a62d", "type": "concept", "title": "Frequency tables, proportions, percentages, rates, and prevalence"}, {"id": "508b59e2-edd3-4644-a499-10d3f8df7ca3", "type": "concept", "title": "Mean, median, mode, quantiles, and trimmed summaries"}, {"id": "92c0105b-7e87-4ec2-b8e7-227ff11781a5", "type": "concept", "title": "Range, interquartile range, variance, standard deviation, and median absolute deviation"}, {"id": "f102a1ed-0d9a-489f-9aee-b821d2409dfc", "type": "concept", "title": "Skewness, outliers, floor and ceiling effects, and robust summaries"}], "description": "Why it matters. Choose summaries that match the scale, shape, and purpose of the data."}, {"id": "5ad5f445-2baa-49fd-8279-903d92ffe614", "type": "subtopic", "title": "Visualization and data quality", "children": [{"id": "42079670-aa11-45ef-a3ff-08dae735aadc", "type": "concept", "title": "Bar charts, histograms, boxplots, dot plots, density displays, and time-series plots"}, {"id": "ac02714f-fcbc-4494-b9f6-c14d06cf6b38", "type": "concept", "title": "Clear titles, denominators, axes, units, uncertainty, accessibility, and source notes"}, {"id": "0e53ad21-030a-41a0-ae39-a57f93b28ce2", "type": "concept", "title": "Missingness, impossible values, duplicates, recoding, and data dictionaries"}, {"id": "633cc58c-6f1d-4a17-a8d0-5b6403e0d18b", "type": "concept", "title": "Misleading scales, truncated axes, overplotting, small cells, confidentiality, and stigmatizing displays"}], "description": "Why it matters. Make patterns and limitations visible before formal testing."}]}, {"id": "4d6f5d13-ec4b-435f-a3f1-db5c34db9206", "type": "topic", "title": "Probability", "description": "Probability provides a language for uncertainty, risk, and variation. Social workers use it to understand screening, prediction, sampling, and the limits of evidence.", "children": [{"id": "723c4ac6-8e66-4615-971e-8cffba1c6853", "type": "subtopic", "title": "Probability foundations", "children": [{"id": "c4768f37-07c4-4ce6-8377-49de9b3a3151", "type": "concept", "title": "Outcomes, events, complements, unions, intersections, and mutually exclusive events"}, {"id": "4e8a4904-c3f5-434a-9a3d-1dfa5de6073b", "type": "concept", "title": "Addition and multiplication rules; independence versus association"}, {"id": "73667d28-d077-49ea-ba56-757abf275f02", "type": "concept", "title": "Conditional probability, joint and marginal probability, and contingency tables"}, {"id": "fd2d2155-8622-47ef-9ef4-23e069e8b98f", "type": "concept", "title": "Base rates, natural frequencies, and common probability misconceptions"}], "description": "Why it matters. Reason carefully about events and conditional information."}, {"id": "39ff8412-ce01-49d6-ad34-ef92b59ef33a", "type": "subtopic", "title": "Distributions and random variables", "children": [{"id": "4880b5ca-568f-4396-a92a-628250132d7d", "type": "concept", "title": "Discrete and continuous random variables; expected value and variance"}, {"id": "fc4824c2-34bb-4bd5-b253-4da6bf0ced7b", "type": "concept", "title": "Bernoulli, binomial, normal, and sampling distributions"}, {"id": "88014237-3b6c-4ceb-9401-5f7683ab6860", "type": "concept", "title": "Standard scores, percentiles, the normal model, and when normality is implausible"}, {"id": "eb1cd27a-deb0-40a1-b437-bb5b34804ee3", "type": "concept", "title": "Central Limit Theorem as a bridge from samples to inference"}], "description": "Why it matters. Use probability models as simplified representations rather than literal truth."}, {"id": "0ae2bc6e-18ab-41b5-af88-cddb6eca611e", "type": "subtopic", "title": "Risk, screening, and decisions", "children": [{"id": "1c0c8943-154f-4594-9785-cc0f8e5370a7", "type": "concept", "title": "Sensitivity, specificity, predictive values, false positives, and false negatives"}, {"id": "03ee822f-2df5-449b-9a40-cf3faf0c08af", "type": "concept", "title": "Prevalence and the base-rate effect on predictive value"}, {"id": "94cc82e1-785d-48a8-b727-e23761e53a47", "type": "concept", "title": "Absolute risk, relative risk, odds, risk difference, and number needed to treat/help"}, {"id": "8a74e6be-78e7-4be3-8795-7734b83e048a", "type": "concept", "title": "Threshold choices, unequal error costs, calibration, fairness, and limits of actuarial tools"}], "description": "Why it matters. Translate probabilities into clinically and ethically meaningful judgments."}]}, {"id": "bda4bed6-a607-4e9e-824e-eef17f9a55e2", "type": "topic", "title": "Sampling", "description": "Sampling determines what population a study can credibly describe. Students learn to separate statistical precision from representativeness and ethical recruitment.", "children": [{"id": "c7d3e38f-e07b-4f15-8de4-0216239d08f7", "type": "subtopic", "title": "Populations and sampling frames", "children": [{"id": "eede98d7-1495-4bd9-a4bb-7673357bf8c6", "type": "concept", "title": "Target, accessible, study, and analytic populations"}, {"id": "c2f5a324-2cee-4226-a318-09cb5519a145", "type": "concept", "title": "Sampling frames, coverage error, eligibility, recruitment, consent, and attrition"}, {"id": "cbc7e188-b75e-4a82-9098-e8700a0b4174", "type": "concept", "title": "Probability versus nonprobability samples"}, {"id": "4059071e-47ce-4c68-b104-a872ef020dc2", "type": "concept", "title": "Agency records, service users, hidden populations, online samples, and community-based recruitment"}], "description": "Why it matters. Define who the evidence is meant to represent and who could actually be reached."}, {"id": "a48d9c9d-47de-4243-a8f7-d0e61d6c05df", "type": "subtopic", "title": "Sampling designs", "children": [{"id": "eaaf8842-4758-4811-9433-09217a4e4193", "type": "concept", "title": "Simple random, systematic, stratified, cluster, and multistage sampling"}, {"id": "bd44340f-b4f6-4b06-b467-d8dc0fc15e76", "type": "concept", "title": "Convenience, purposive, quota, snowball, respondent-driven, and time-location sampling"}, {"id": "1aec6a99-92f1-4ff2-8672-104c82a29fd6", "type": "concept", "title": "Oversampling small or marginalized groups and the need for weights"}, {"id": "d60f8879-f8ae-4cee-a81e-66a82a782467", "type": "concept", "title": "Design effects, intraclass correlation, finite populations, and multilevel structure"}], "description": "Why it matters. Match a design to logistics, equity, and analytic goals."}, {"id": "55ca1311-d121-4650-9b12-fbaa44f61daf", "type": "subtopic", "title": "Bias, precision, and power", "children": [{"id": "5f18b5b3-dfbd-4e47-97fd-8a88556f5e9c", "type": "concept", "title": "Sampling variability, standard errors, margins of error, and confidence levels"}, {"id": "68c1da81-cc6c-4234-92b7-902403c7978f", "type": "concept", "title": "Selection, nonresponse, survivorship, volunteer, and attrition bias"}, {"id": "6aa12a5f-6b03-4f32-82e3-0725dcc1be11", "type": "concept", "title": "Power, minimum detectable effect, practical significance, and feasibility"}, {"id": "937a05de-99b2-4001-ad3b-cbaa83354da0", "type": "concept", "title": "Weighting, poststratification, missing-data adjustments, and transparent limits to generalization"}], "description": "Why it matters. Distinguish the size of a sample from the quality of its information."}]}, {"id": "383787dd-9422-46db-9de4-819c61c5e47c", "type": "topic", "title": "Hypothesis testing and estimation", "description": "Statistical inference quantifies how compatible the observed data are with models and hypotheses. The goal is calibrated evidence, not a mechanical hunt for p-values.", "children": [{"id": "684795cb-c80d-4429-9c27-981d04605d32", "type": "subtopic", "title": "Questions, estimands, and hypotheses", "children": [{"id": "cd508144-28a0-4b23-97fe-7e3331820d95", "type": "concept", "title": "Research question, population, comparison, outcome, time, and estimand"}, {"id": "9230c588-30c1-4420-92e9-89e54ffffaea", "type": "concept", "title": "Null and alternative hypotheses; directional and nondirectional tests"}, {"id": "aa6b2c62-8308-4e73-9599-1d603438d58e", "type": "concept", "title": "Point estimates, standard errors, sampling distributions, and confidence intervals"}, {"id": "bf944c2e-c14b-4916-b22b-996ababa9c03", "type": "concept", "title": "Descriptive, associational, predictive, and causal questions"}], "description": "Why it matters. Start with the decision-relevant quantity before choosing a test."}, {"id": "358249bb-8f39-4260-9f37-00b2bf9efc86", "type": "subtopic", "title": "Testing logic and errors", "children": [{"id": "f0bdaa5c-4a87-41f8-89ca-afafc3d9a319", "type": "concept", "title": "Test statistics, p-values, alpha, and rejection regions"}, {"id": "cfd71c49-5063-4ce1-959b-bc0510ddb123", "type": "concept", "title": "Type I and Type II errors, power, and consequences of errors"}, {"id": "c1b273fb-ee4b-464c-b8d7-9fe7fcfcc799", "type": "concept", "title": "Statistical significance versus effect size, precision, practical importance, and equity"}, {"id": "3136168b-d1b9-434a-a824-5c9a319cdbac", "type": "concept", "title": "Multiple testing, selective reporting, p-hacking, preregistration, and replication"}], "description": "Why it matters. Interpret uncertainty without treating a threshold as proof."}, {"id": "b2a0dda2-354e-4682-b794-ef60b841dd4a", "type": "subtopic", "title": "Assumptions and transparent reporting", "children": [{"id": "7803a7da-0262-4102-a8f6-f29621a67ea5", "type": "concept", "title": "Independence, distributional shape, equal variance, scale, and sample-size conditions"}, {"id": "eea13aee-64ac-4763-9d24-b0fd7ac4fe80", "type": "concept", "title": "Outliers, influential cases, missingness, and sensitivity analysis"}, {"id": "b40a574e-1446-4404-9c60-f93340481b39", "type": "concept", "title": "Exact tests, permutation approaches, bootstrap intervals, and nonparametric alternatives"}, {"id": "6359f50c-566c-4379-8f2e-2d0d630c5568", "type": "concept", "title": "Estimate, interval, test statistic, degrees of freedom, p-value, effect size, assumptions, and limitations"}], "description": "Why it matters. Check whether the analysis is appropriate and report enough for others to evaluate it."}]}, {"id": "b1f71877-dc5b-4328-b030-4c54a78462ae", "type": "topic", "title": "Chi-square and categorical data", "description": "Chi-square methods test patterns among categorical variables common in social-work data, while effect sizes and cell counts reveal what a p-value alone cannot.", "children": [{"id": "24bee209-2c1a-46dc-a625-265368600025", "type": "subtopic", "title": "Tables and questions", "children": [{"id": "23146828-525e-42bf-9db2-933391bd1489", "type": "concept", "title": "Counts versus row, column, and total percentages"}, {"id": "d5672afc-11f7-4ae3-9534-00a6e2836061", "type": "concept", "title": "Tests of independence, homogeneity, and goodness of fit"}, {"id": "066c7ac0-d6d4-4abd-b5dc-ddcffe4f1472", "type": "concept", "title": "Observed and expected counts; residuals and contribution to chi-square"}, {"id": "133c2bfc-ecc1-48da-bd16-92276816a6ec", "type": "concept", "title": "Risk difference, risk ratio, odds ratio, and prevalence ratio"}], "description": "Why it matters. Build interpretable cross-tabulations with appropriate denominators."}, {"id": "7a279c00-58a9-4da1-8de2-a916371b0b83", "type": "subtopic", "title": "Conditions and alternatives", "children": [{"id": "bd0b2f50-1bf1-492b-bd5c-a374cb3ce5e6", "type": "concept", "title": "Independent observations, mutually exclusive categories, and adequate expected counts"}, {"id": "05ffd734-5ecc-4785-bc06-6e1cef99fcb2", "type": "concept", "title": "Sparse cells, structural zeros, small groups, and disclosure risk"}, {"id": "e4076c31-8ac6-48a8-bd6c-6df87a85ccc3", "type": "concept", "title": "Fisher exact test, exact or Monte Carlo methods, and category decisions"}, {"id": "cbb90616-52c4-44e5-a2ff-538a7609ddeb", "type": "concept", "title": "Paired binary data and McNemar test as a distinct design"}], "description": "Why it matters. Recognize when asymptotic chi-square results are unreliable."}, {"id": "c109616a-c001-4fcb-b675-eddf9f3532ca", "type": "subtopic", "title": "Interpretation for practice", "children": [{"id": "fe46ef8d-0b94-45f7-a2d4-737b13922613", "type": "concept", "title": "Cramer V, phi, odds ratios, and confidence intervals"}, {"id": "946331f5-0a7b-4ab0-aecb-320d4f43bd40", "type": "concept", "title": "Stratified tables, confounding, Simpson paradox, and effect modification"}, {"id": "dc29de72-5689-4a8e-a014-db4a160cf2db", "type": "concept", "title": "Adjusted residuals and careful follow-up comparisons"}, {"id": "35ba33a3-abe0-486a-ba53-6cd9ae763a76", "type": "concept", "title": "Avoiding causal language, deficit framing, and overinterpretation of small subgroup cells"}], "description": "Why it matters. Describe the pattern, size, uncertainty, and limitations."}]}, {"id": "cbda4a14-2e3e-4712-bc68-ea1e332c3f96", "type": "topic", "title": "t-tests and mean comparisons", "description": "t-tests compare means while accounting for sampling variability. Students learn that design, assumptions, effect size, and interval estimates matter more than memorizing formulas.", "children": [{"id": "f65f7bd5-ee72-4546-a629-2a2d255828f3", "type": "subtopic", "title": "Choosing the comparison", "children": [{"id": "248ebe0b-8be4-44a0-80f7-cd87292a8ce5", "type": "concept", "title": "One-sample t-test for a benchmark"}, {"id": "df82480e-112f-463d-8fe1-87d231872eab", "type": "concept", "title": "Independent-samples t-test for separate groups"}, {"id": "031030b9-44bf-4448-af5e-a54f808e6d79", "type": "concept", "title": "Paired-samples t-test for matched or repeated observations"}, {"id": "cb9fd5d6-07d6-4bad-880e-d9bf1de43eb6", "type": "concept", "title": "Difference scores, pairing, independence, and clustering"}], "description": "Why it matters. Select the test from the study design, not from the desired result."}, {"id": "7d4c9786-98a6-4947-8a22-5ec416256208", "type": "subtopic", "title": "Assumptions and robust choices", "children": [{"id": "86fd958b-c885-4d1e-904b-5f822ca76588", "type": "concept", "title": "Approximate normality of outcomes or differences; sample-size robustness"}, {"id": "af3e9ce7-7c46-46aa-aff5-50b6412e67f9", "type": "concept", "title": "Welch t-test versus pooled-variance t-test"}, {"id": "e813add5-f3c9-441d-9515-5f8d182afc6e", "type": "concept", "title": "Outliers, skew, bounded scales, and unequal group sizes"}, {"id": "d910c23a-7b75-4ed9-9092-b88b73c7afa4", "type": "concept", "title": "Mann-Whitney, Wilcoxon signed-rank, permutation tests, bootstrap intervals, and their estimands"}], "description": "Why it matters. Evaluate whether mean-based comparison is sensible."}, {"id": "5cf436f7-897a-4a4d-bb3f-db599d58d047", "type": "subtopic", "title": "Effect and reporting", "children": [{"id": "eaedac98-5268-4fcb-9e85-18ad9d60a271", "type": "concept", "title": "Mean difference, standardized mean difference, and confidence interval"}, {"id": "a0039708-a55c-45a3-8640-018b2d86a244", "type": "concept", "title": "Cohen d, Hedges g, paired effect sizes, and practical benchmarks"}, {"id": "42267abd-9917-46c1-87c4-c52ff425c6ac", "type": "concept", "title": "Graphing raw data with summaries rather than bar charts alone"}, {"id": "864a0502-686d-413e-aa44-855484bcd4c3", "type": "concept", "title": "APA-style results plus plain-language and practice implications"}], "description": "Why it matters. Communicate magnitude and uncertainty in terms relevant to clients and programs."}]}, {"id": "acf22144-1384-4938-9739-8469f80cb5ff", "type": "topic", "title": "Analysis of variance", "description": "ANOVA extends mean comparison to multiple groups or conditions. It separates an omnibus question from planned contrasts and guards against uncontrolled testing.", "children": [{"id": "fb0ac33d-fddc-4f43-a3fc-a3e274c9f136", "type": "subtopic", "title": "ANOVA logic and designs", "children": [{"id": "21dca89f-cc92-4613-bdfe-5bf01aa56432", "type": "concept", "title": "Between-group and within-group variation; F statistic"}, {"id": "1d3ec3a2-8df1-43e0-ad8c-ad23e545fb6d", "type": "concept", "title": "One-way between-subjects ANOVA"}, {"id": "afe10da1-6b50-4ce0-9bf2-db3efd431505", "type": "concept", "title": "Repeated-measures and factorial designs as extensions"}, {"id": "d0da57d1-fe57-4d8c-a205-0c2c00065bca", "type": "concept", "title": "Main effects, interactions, nesting, and the limits of simple one-way models"}], "description": "Why it matters. Understand what variance decomposition asks and what it does not establish."}, {"id": "25362c42-b5b6-4c36-b001-a6d5c6e4029d", "type": "subtopic", "title": "Assumptions and follow-up", "children": [{"id": "29e67f34-71b9-44a1-b82e-b2a21f366ce4", "type": "concept", "title": "Independence, residual normality, homogeneity, and influential observations"}, {"id": "efee49b5-0bb3-4f63-ba7a-3b8d05d015f0", "type": "concept", "title": "Welch ANOVA, Kruskal-Wallis, Friedman, permutation, and robust alternatives"}, {"id": "c000c7a1-3fb8-4166-9ed1-754aeea025b1", "type": "concept", "title": "Planned contrasts versus post hoc comparisons"}, {"id": "a9611e35-9dbc-4cc3-bd41-4f2f2dd0e9a7", "type": "concept", "title": "Tukey, Holm, false discovery rate, and familywise error control"}], "description": "Why it matters. Plan comparisons before examining the results when possible."}, {"id": "2c41fbd0-3aa6-43a6-8967-caba444f294a", "type": "subtopic", "title": "Magnitude and interpretation", "children": [{"id": "3113a6d2-ab13-41c2-94f9-971e0f670782", "type": "concept", "title": "Eta squared, omega squared, partial eta squared, and confidence intervals"}, {"id": "1cb3c761-791e-46ee-98cc-4695342ca231", "type": "concept", "title": "Estimated means, contrasts, raw-data plots, and uncertainty intervals"}, {"id": "4cf8c30a-8864-4747-acaf-016e6d093111", "type": "concept", "title": "Interaction plots and heterogeneous program effects"}, {"id": "8fe5884a-a807-46e7-bb62-a7a9597ee284", "type": "concept", "title": "Substantive importance, unequal opportunity, subgroup power, and cautious interpretation"}], "description": "Why it matters. Move beyond a significant omnibus result to meaningful group patterns."}]}, {"id": "c06e28b7-695b-4bdc-b4d1-990e2a635cce", "type": "topic", "title": "Correlation", "description": "Correlation describes how two variables vary together. Students learn to visualize relationships, choose a suitable coefficient, and resist causal interpretations.", "children": [{"id": "c945ba9f-ae96-4c07-8d07-fe30368e76ff", "type": "subtopic", "title": "Association concepts", "children": [{"id": "e7ed2d12-4921-40f0-9dd2-049deb25c53c", "type": "concept", "title": "Scatterplots, covariance, direction, magnitude, and linearity"}, {"id": "eadd76ff-04f5-4650-9ad5-0c17cb512088", "type": "concept", "title": "Pearson correlation and its assumptions"}, {"id": "b834ac4a-b799-4b26-b489-63c7da1fade6", "type": "concept", "title": "Spearman rank and Kendall association for ordinal or monotonic relationships"}, {"id": "9bbc9c87-54da-448b-974b-0633808ddd9d", "type": "concept", "title": "Point-biserial correlation and categorical-variable cautions"}], "description": "Why it matters. Separate direction, strength, form, and prediction."}, {"id": "1afc8053-5fe3-44a7-b924-51e4f1e052d5", "type": "subtopic", "title": "Threats and diagnostics", "children": [{"id": "b4efaad4-8785-4d67-87d3-c75a6f296dfe", "type": "concept", "title": "Outliers, restricted range, nonlinearity, heteroscedasticity, and measurement error"}, {"id": "a40fbad9-d623-4895-9c07-34b653e46ff6", "type": "concept", "title": "Subgroups, ecological fallacy, aggregation, and Simpson paradox"}, {"id": "4f11cee9-b4bc-4d8f-8c1f-93a6c89a960d", "type": "concept", "title": "Common causes, reverse direction, selection, and collider bias"}, {"id": "ed9a5d73-8262-4ffe-a66b-44df41c76dfe", "type": "concept", "title": "Multiple correlations, researcher degrees of freedom, and correction strategies"}], "description": "Why it matters. Identify patterns that can make a coefficient misleading."}, {"id": "d8205f29-b8e7-4d1c-bf51-db4b622abb2d", "type": "subtopic", "title": "Interpretation and communication", "children": [{"id": "8556fdf6-8a57-44df-8670-8a0c725947cf", "type": "concept", "title": "Correlation coefficient, confidence interval, sample size, and plot"}, {"id": "a59d1e57-c5cb-40b0-ac1b-876a74be6104", "type": "concept", "title": "Shared variance and why r-squared is not the percent “caused”"}, {"id": "77a39fc4-d414-47d0-83f1-50d573ea6fd3", "type": "concept", "title": "Practical magnitude depends on outcome, setting, reliability, and decision stakes"}, {"id": "0171dce2-7c39-4f94-ac78-f3cb30e57969", "type": "concept", "title": "Association language, uncertainty, and implications for further study or screening"}], "description": "Why it matters. Report the relationship with uncertainty and context."}]}, {"id": "d3a89a6e-9bd6-4c32-b93f-bd2ddba6269f", "type": "topic", "title": "Regression", "description": "Regression estimates adjusted relationships and supports prediction, but valid interpretation depends on design, specification, diagnostics, and a clear estimand.", "children": [{"id": "da9bff74-d36d-4500-b14a-7696eb56344e", "type": "subtopic", "title": "Simple and multiple regression", "children": [{"id": "9f4d76f6-917f-44d8-9f44-dd57f8daed84", "type": "concept", "title": "Intercept, slope, fitted value, residual, and R-squared"}, {"id": "215c4b6a-04a4-446e-86b2-74216379a609", "type": "concept", "title": "Continuous, binary, categorical, and transformed predictors"}, {"id": "a1974140-9a47-4278-94d2-306e27a71294", "type": "concept", "title": "Dummy coding, reference categories, centering, and standardized coefficients"}, {"id": "664af684-37ed-4acf-8cff-f90f5eec79e8", "type": "concept", "title": "Confounding adjustment, mediation and interaction as distinct questions"}], "description": "Why it matters. Translate a social-work question into an outcome, predictors, and interpretable coefficients."}, {"id": "b1b24da9-a53a-490a-a95d-c2509f178b05", "type": "subtopic", "title": "Model diagnostics and uncertainty", "children": [{"id": "f728c995-2d4a-427b-a494-b8a6ba5104b9", "type": "concept", "title": "Linearity, independence, homoscedasticity, residual distribution, and specification"}, {"id": "aee9696c-f6c8-4fa8-a53e-ebeb0d973329", "type": "concept", "title": "Multicollinearity, variance inflation, influential cases, leverage, and Cook distance"}, {"id": "9d0c0c3e-bd16-4f6d-a3b1-92db9c224b8b", "type": "concept", "title": "Missing data, complete-case analysis, imputation concepts, and sensitivity analysis"}, {"id": "c952b7a1-0290-4282-89be-b07de2b01396", "type": "concept", "title": "Overfitting, train-test separation, cross-validation, and prediction error"}], "description": "Why it matters. Check whether the fitted model adequately represents the data."}, {"id": "5506a626-4d0e-4b97-9e75-653a9ca3254d", "type": "subtopic", "title": "Interpretation, extensions, and ethics", "children": [{"id": "ac97744c-1b92-447b-9aa2-e0c29b33219d", "type": "concept", "title": "Coefficient and confidence-interval interpretation; adjusted predictions and marginal effects"}, {"id": "0ce42e68-cc21-44f3-b203-a9932119187a", "type": "concept", "title": "Logistic regression for binary outcomes and count models as next steps"}, {"id": "02841a5e-f0d6-4872-8b6a-dd92c2e0d8c9", "type": "concept", "title": "Prediction versus explanation versus causal effect; design assumptions for causal claims"}, {"id": "0a7f6843-fe03-43a6-b01b-9a599e42df5a", "type": "concept", "title": "Algorithmic bias, proxy variables, fairness, transparency, and human review in high-stakes decisions"}], "description": "Why it matters. Use regression estimates for the right purpose and communicate limitations."}]}, {"id": "a268d56a-dbe6-4ab5-8f32-83a5e75a5974", "type": "topic", "title": "Statistical software and reproducible practice", "description": "Software should make analysis auditable, not turn judgment into button pressing. Students create a complete workflow from raw data to a defensible result and accessible communication.", "children": [{"id": "01441f75-185f-4e32-98ea-2b38f6f4de98", "type": "subtopic", "title": "Data management workflow", "children": [{"id": "23182a1d-03a4-4679-bca2-fdf1970adc1c", "type": "concept", "title": "Import, variable labels, types, value labels, missing-value codes, and date handling"}, {"id": "f9974970-29ee-4e0d-a538-f83c1b10133e", "type": "concept", "title": "Tidy structure, recoding, derived variables, validation checks, and data dictionaries"}, {"id": "d9086332-6796-44f0-b6f2-582bea5ecb22", "type": "concept", "title": "De-identification, small-cell suppression, secure storage, access control, and retention"}, {"id": "22f3cc35-8792-4f40-8006-a79c58e881c9", "type": "concept", "title": "Raw/read-only, cleaned, analytic, output, and documentation folders"}], "description": "Why it matters. Protect source data while documenting every transformation."}, {"id": "4e7291ef-9a3f-42ea-9bee-69abfd653663", "type": "subtopic", "title": "Reproducible analysis", "children": [{"id": "fb1b156c-a029-47cb-9a1b-175f672c5c56", "type": "concept", "title": "Syntax/scripts rather than undocumented point-and-click steps"}, {"id": "a5e0f520-2238-4ba1-854d-9e080783843d", "type": "concept", "title": "Comments, file paths, seeds, session/software versions, and analysis logs"}, {"id": "a5c4c517-3085-41b6-8660-4f87d4899280", "type": "concept", "title": "Automated tables and figures; export without manual transcription"}, {"id": "dcf4c922-467b-415b-9ccd-be96050937e2", "type": "concept", "title": "Version control concepts, quality checks, reproducibility package, and audit trail"}], "description": "Why it matters. Make results traceable and rerunnable in SPSS syntax, R, jamovi, JASP, or approved software."}, {"id": "e31b6501-30e1-43b5-bf2e-5d80f4f18239", "type": "subtopic", "title": "Practice-facing interpretation", "children": [{"id": "ac34fb4d-4c36-48a0-a3ac-132d74ea2cf2", "type": "concept", "title": "Test selection map based on question, design, variable type, and assumptions"}, {"id": "24a71024-81db-441a-a5f6-091f3017c3f0", "type": "concept", "title": "Tables and graphs that include denominators, estimates, uncertainty, and accessible design"}, {"id": "26dd1274-a93b-498a-bc5b-5b59ec49072d", "type": "concept", "title": "Plain-language results for clients, practitioners, administrators, and community partners"}, {"id": "8d7bd74e-5db0-48df-a48b-5ea16f8e80e8", "type": "concept", "title": "Data-story limits, equity impacts, recommendations, and questions that remain unanswered"}], "description": "Why it matters. Translate numerical output into responsible decisions and evidence-based practice."}]}], "dbBacked": true}$stswjson$::jsonb,
  is_catalog = true,
  is_private = false,
  owner_id = null,
  kind = 'course',
  visibility = 'public',
  updated_at = now()
where slug = 'statistics-for-social-work'
  and (kind is null or kind = 'course');
