  ('3fc412ee-05b2-4507-8e38-bdae5bb503bd', 'c0d1e2f3-5a6b-4c60-9d90-0e1f2a3b4c00', null, 'topic'::public.curated_course_node_type, 'Descriptive statistics', 'Descriptive statistics turn case, agency, and community data into an honest picture of who was observed and what patterns are present. They are the foundation for every later analysis.', 0),
