  ('633cc58c-6f1d-4a17-a8d0-5b6403e0d18b', 'c0d1e2f3-5a6b-4c60-9d90-0e1f2a3b4c00', '5ad5f445-2baa-49fd-8279-903d92ffe614', 'concept'::public.curated_course_node_type, 'Misleading scales, truncated axes, overplotting, small cells, confidentiality, and stigmatizing displays', null, 3),
  ('4d6f5d13-ec4b-435f-a3f1-db5c34db9206', 'c0d1e2f3-5a6b-4c60-9d90-0e1f2a3b4c00', null, 'topic'::public.curated_course_node_type, 'Probability', 'Probability provides a language for uncertainty, risk, and variation. Social workers use it to understand screening, prediction, sampling, and the limits of evidence.', 1),
