  ('4e8a4904-c3f5-434a-9a3d-1dfa5de6073b', 'c0d1e2f3-5a6b-4c60-9d90-0e1f2a3b4c00', '723c4ac6-8e66-4615-971e-8cffba1c6853', 'concept'::public.curated_course_node_type, 'Addition and multiplication rules; independence versus association', null, 1),
