  ('fd2d2155-8622-47ef-9ef4-23e069e8b98f', 'c0d1e2f3-5a6b-4c60-9d90-0e1f2a3b4c00', '723c4ac6-8e66-4615-971e-8cffba1c6853', 'concept'::public.curated_course_node_type, 'Base rates, natural frequencies, and common probability misconceptions', null, 3),
