  ('88014237-3b6c-4ceb-9401-5f7683ab6860', 'c0d1e2f3-5a6b-4c60-9d90-0e1f2a3b4c00', '39ff8412-ce01-49d6-ad34-ef92b59ef33a', 'concept'::public.curated_course_node_type, 'Standard scores, percentiles, the normal model, and when normality is implausible', null, 2),
  ('eb1cd27a-deb0-40a1-b437-bb5b34804ee3', 'c0d1e2f3-5a6b-4c60-9d90-0e1f2a3b4c00', '39ff8412-ce01-49d6-ad34-ef92b59ef33a', 'concept'::public.curated_course_node_type, 'Central Limit Theorem as a bridge from samples to inference', null, 3),
