  ('8a74e6be-78e7-4be3-8795-7734b83e048a', 'c0d1e2f3-5a6b-4c60-9d90-0e1f2a3b4c00', '0ae2bc6e-18ab-41b5-af88-cddb6eca611e', 'concept'::public.curated_course_node_type, 'Threshold choices, unequal error costs, calibration, fairness, and limits of actuarial tools', null, 3),
  ('bda4bed6-a607-4e9e-824e-eef17f9a55e2', 'c0d1e2f3-5a6b-4c60-9d90-0e1f2a3b4c00', null, 'topic'::public.curated_course_node_type, 'Sampling', 'Sampling determines what population a study can credibly describe. Students learn to separate statistical precision from representativeness and ethical recruitment.', 2),
  ('c7d3e38f-e07b-4f15-8de4-0216239d08f7', 'c0d1e2f3-5a6b-4c60-9d90-0e1f2a3b4c00', 'bda4bed6-a607-4e9e-824e-eef17f9a55e2', 'subtopic'::public.curated_course_node_type, 'Populations and sampling frames', 'Why it matters. Define who the evidence is meant to represent and who could actually be reached.', 0),
