  ('a48d9c9d-47de-4243-a8f7-d0e61d6c05df', 'c0d1e2f3-5a6b-4c60-9d90-0e1f2a3b4c00', 'bda4bed6-a607-4e9e-824e-eef17f9a55e2', 'subtopic'::public.curated_course_node_type, 'Sampling designs', 'Why it matters. Match a design to logistics, equity, and analytic goals.', 1),
  ('eaaf8842-4758-4811-9433-09217a4e4193', 'c0d1e2f3-5a6b-4c60-9d90-0e1f2a3b4c00', 'a48d9c9d-47de-4243-a8f7-d0e61d6c05df', 'concept'::public.curated_course_node_type, 'Simple random, systematic, stratified, cluster, and multistage sampling', null, 0);
