  ('cbda4a14-2e3e-4712-bc68-ea1e332c3f96', 'c0d1e2f3-5a6b-4c60-9d90-0e1f2a3b4c00', null, 'topic'::public.curated_course_node_type, 't-tests and mean comparisons', 't-tests compare means while accounting for sampling variability. Students learn that design, assumptions, effect size, and interval estimates matter more than memorizing formulas.', 5),
